window.TOPO={"sectors":[{"id":1,"name":"Rêve d'enfant","gloss":"Child's Dream","color":"#c9c42c","stats":{"routes":23,"grades":"4a – 6a","aspect":"South-facing","height":"3 m to 18 m"},"intro":"p05","notes":["Small sector with a lot of vegetation.","The bolts are fairly close together.","Even on the easy routes the holds can be far apart — the climbing is often reachy for very young children.","The base of the routes is not always very comfortable for belaying.","Routes 17 to 23 start from a promontory where you should clip yourself in (self-belay) for extra safety."],"topos":[{"page":"p06","routes":"1–7"},{"page":"p07","routes":"8–16"},{"page":"p08","routes":"17–23"}],"routes":[["1","Miniclimb","","4a","3 m","Short, low-angled slab.","p06"],["2","Yosenain","","4a","3 m","Short, low-angled slab.","p06"],["3","Eléphantillage","pun: elephant + 'sample'","4a","5 m","Big flake.","p06"],["4","Conte du premier œuf","Tale of the First Egg","4a","8 m","Crack in a corner.","p06"],["5","Rêve d'enfant","Child's Dream","4b","10 m","Short pillar.","p06"],["6","Papy boom","Grandpa Boom","4b","10 m","Crack.","p06"],["7","Hamster jovial","Jolly Hamster","5c","10 m","Slab with crimps.","p06"],["8","Goldovrac","","4a","10 m","Corner (dihedral).","p07"],["9","Gromignon","Big Cutie","4b","10 m","Corner (dihedral).","p07"],["10","Telemoche","","5b","15 m","Low-angled slab.","p07"],["11","Salut monchus","","6a","18 m","Corner and bulge.","p07"],["12","Fear and desire","","5b","15 m","Vague corner.","p07"],["13","Le maître des abeilles","The Master of the Bees","6a","15 m","Overhang and crack.","p07"],["14","A chacun ses croûtes","To Each Their Own Scabs","4c","15 m","Big angular corner.","p07"],["15","Mon petit sceau et ma truelle","My Little Bucket and My Trowel","5c","12 m","Slab.","p07"],["16","Fantasia","","4b","10 m","Crack and leaning slab.","p07"],["17","Anal plus","","5a","10 m","Leaning pillar.","p08"],["18","Restos du cœur","Restaurants of the Heart (a French food charity)","4a","8 m","Overhanging corner.","p08"],["19","Free go","","4a","8 m","Big chimney crack.","p08"],["20","Le dernier ampère heure","The Last Amp-Hour","4b","8 m","Vague cracks.","p08"],["21","Pipi caca","Pee-Pee Poo-Poo","4a","8 m","Big, short corner.","p08"],["22","Tête de turc","Whipping Boy","5c","10 m","Cracked slab.","p08"],["23","Ragots intimes","Intimate Gossip","5b","10 m","Slab and small roof.","p08"]]},{"id":2,"name":"Pimprenelle","gloss":"Burnet (a wildflower)","color":"#5f8f96","stats":{"routes":25,"grades":"4a – 6b","aspect":"South & East-facing","height":"18 m to 25 m"},"intro":"p09","notes":["Sector with fairly closely spaced bolts.","Lots of ledges in this sector (the old Saffres quarries).","Pay attention to belaying, and to the quality of some holds (the rock is sometimes loose/fractured).","Route grades suited to a first introduction to outdoor climbing."],"topos":[{"page":"p10","routes":"24–37"},{"page":"p11","routes":"38–48"}],"routes":[["24","Baston la baffe","Fight, the Slap","4c","18 m","Vague crack and slab arête.","p10"],["25","Exogénose aigüe","Acute Exogenosis","4b","20 m","Pillar, crack.","p10"],["26","Les gars de la narine","The Nostril Guys","4a","20 m","Slab and vague corner.","p10"],["27","Adèle s'en mêle","Adèle Gets Involved","4a","20 m","Corner broken up by ledges.","p10"],["28","Yeti y es-tu","Yeti, Are You There?","4b","20 m","Slab and slab arête.","p10"],["29","L'émotion des artistes","The Artists' Emotion","5a","22 m","Overhang, ledge and corner.","p10"],["30","Période mystique","Mystic Period","4b","22 m","Slab, irregular corner and overhang.","p10"],["31","Zébu","Zebu","5c+","22 m","Slab, pillar and crack.","p10"],["32","Bullons","Let's Laze Around","5a","22 m","Corner, steep section, corner.","p10"],["33","Mère michu","Mother Michu (French nursery rhyme)","5c","22 m","Crack, corner and slab.","p10"],["34","Pimprenelle","Burnet","5b","20 m","Corner, flake and slab.","p10"],["35","La valse des minous","The Kitties' Waltz","5a+","20 m","Overhang and low-angled slab. A boulder-problem move at the start.","p10"],["36","Bordel de randonnée","Hiking Mess","4c","22 m","Slab, ledge and corner.","p10"],["37","Viandax","","5a","22 m","Corner, ledge and big crack. Very sculpted rock. 2 possible finishes of the same grade.","p10"],["38","Tampox","","6a","22 m","Slab with big steps, then a crack.","p11"],["39","Vie et mœurs","Life and Customs","5c+","25 m","Crimpy slab and crack.","p11"],["40","Enfermé dans les cabinets","Locked in the Toilet","6b","25 m","Crimpy slab.","p11"],["41","Dessine-moi une escalade","Draw Me a Climb","6a+","25 m","Overhanging slab.","p11"],["42","Parlez-moi d'humour","Talk to Me About Humour","5b / 5c","25 m","Corner and cracked slab. Left variant: 5b | right variant: 5c.","p11"],["43","La promesse de l'ange","The Angel's Promise","6a","25 m","Crimpy slab.","p11"],["44","Les saisons du plaisir","The Seasons of Pleasure","6a","25 m","Overhanging crack, ledge and compact slab.","p11"],["45","Rêve de prises","Dream of Holds","5b","25 m","Vague pillar, corner.","p11"],["46","Liberté tous risques","Freedom, All Risks","5c","25 m","Overhanging pillar, crack and slab. Finish in the corner of route 47.","p11"],["47","Trace d'éternité","Trace of Eternity","4c","25 m","Corner, often overgrown with vegetation.","p11"],["48","Ruissellement d'émotion","Streaming Emotion","5c+","18 m","Vertical, cracked slab.","p11"]]},{"id":3,"name":"Floconnerie","gloss":"","color":"#1f8a4c","stats":{"routes":22,"grades":"4a – 7c","aspect":"South & East-facing","height":"18 m to 25 m"},"intro":"p12","notes":["Sector with lots of corners (dihedrals). Quite shady and very pleasant on hot days.","Some historic lines.","The rock is sometimes loose/fractured — be very careful.","On the other hand, some routes are of exceptional quality."],"topos":[{"page":"p13","routes":"49–60"},{"page":"p14","routes":"61–70"}],"routes":[["49","Le siège","The Seat","4a","18 m","Well bolted. A ledge in the middle breaks up the route and its consistency a bit.","p13"],["50","L'appui tête","The Headrest","5a","22 m","Joins route 49 at the ledge.","p13"],["51","Odyssée dudulesque","","5c","22 m","Same start as route 50, then head left to reach a cracked slab with nice balance moves. Not very consistent.","p13"],["52","Rillettes à tous les étages","Rillettes on Every Floor","7a","22 m","Bouldery, needs determination. Easier finish.","p13"],["53","Pollution intime","Intimate Pollution","6b","25 m","Very nice route at the grade. Short and pumpy, with some steepness. Nice, very physical moves.","p13"],["54","Dièdre à Leblanc","Leblanc's Corner","5c","25 m","Historic, legendary route at the grade. Slightly polished as the route gets little rain. Sustained and consistent.","p13"],["55","Floconnerie","","6a","25 m","A must at the grade. Somewhat disconcerting climbing on quartz, all on smooth slab. A great classic.","p13"],["56","Chute ascensionnelle","Upward Fall","6b+","25 m","Difficulties in the first 15 m, with a roof that is technical for the feet; finishes up route 55.","p13"],["57","L'encombrée","The Cluttered One","5b","25 m","Chimneying technique to the fore. A very particular style — love it or hate it, your choice.","p13"],["58","Bamboche","Binge","6c","25 m","Not consistent but varied. Loose rock at the start. The roof may put some people off but is quite interesting, and the slab finish is classy.","p13"],["59","Liaisons dangereuses","Dangerous Liaisons","5c","25 m","Start up 60 and traverse to reach the chimney of route 57. Not uninteresting, but not the best route at the grade.","p13"],["60","Combat dans l'île de velours","Fight on Velvet Island","6b","25 m","Starts on loose rock; the rest is quite disconcerting, following the line of the arête. A nice route all the same.","p13"],["61","L'étagée","The Tiered One","6a","25 m","Not consistent, but interesting overall with a nice slab to finish.","p14"],["62","No suture","","6a","25 m","Progressive difficulty. Physical finger-jamming crack where you shouldn't hang around too long. Fun route.","p14"],["63","Gand vé","","5a / 5b+","25 m","A historic route, all in a corner. Layback, bridging, smearing: every technique gets a turn. Finish left 5a, or finish right a solid 5b+.","p14"],["64","Micropore et maxitruie","Micropore and Maxi-Sow","6b","25 m","25 m line with an original path, all traversing. Fun, airy finish.","p14"],["65","Très mauvaise","Very Bad","5c+","25 m","Consistent and athletic. First part overhanging on big holds. Fairly technical corner at the top.","p14"],["66","Examains de passage","Passing Exams (pun on 'hands')","6b","25 m","Sustained and consistent route with varied styles. A nice, sometimes surprising route.","p14"],["67","Zone érogène","Erogenous Zone","7a","25 m","Finishing variant of 66. Awkward crack climbing, technical, needs real determination.","p14"],["68","La hulotte","The Tawny Owl","7b+","25 m","Varied, sustained climbing, mostly on fingers. Rounded crack and slopers at the top. Bouldery.","p14"],["69","Les rampants du roc","The Rock Crawlers","7c","25 m","Bouldery route. Few footholds at the crux, and crack technique to the fore.","p14"],["70","Le singe","The Monkey","5c+","25 m","Overhanging on jugs — a nice, original route. 6a if you finish on the right.","p14"]]},{"id":4,"name":"Les Auxerrois","gloss":"The People of Auxerre","color":"#e98d6f","stats":{"routes":29,"grades":"4b – 7a+","aspect":"South-facing","height":"15 m to 25 m"},"intro":"p15","notes":["Sector to the right of the Grotte aux Filles ('Girls' Cave', route 93).","This sector is quite shady, with routes at accessible grades that are fairly short overall.","Still, stay alert to the rock quality, which can sometimes be poor, even if it is fairly compact overall."],"topos":[{"page":"p16","routes":"71–79"},{"page":"p17","routes":"80–90"},{"page":"p18","routes":"91–99"}],"routes":[["71","Coquille's club","","6a","25 m","Nice route at the grade.","p16"],["72","Les guidochons","","5c","25 m","Consistent and athletic. Very vertical corner with some quite surprising Buoux-style pockets. A classic at the grade.","p16"],["73","Vue de profil","Profile View","6c","25 m","Start up 72, then follow the pillar. Technical climbing on an arête. Surprising.","p16"],["74","Les Auxerrois","The People of Auxerre","5c+","25 m","Nicely continuous. Rising traverse; finish either in the corner of Le Singe (route 70) or in Coquille's Club (route 71). Traverses were in fashion in the '80s.","p16"],["75","Zest de fissure","A Zest of Crack","7a+","25 m","Bouldery. The rock on the slab is very compact. Technical and demanding on the feet.","p16"],["76","Banane Blues","Banana Blues","7a","25 m","Consistent. Very nice route on decent holds that needs speed and determination. Quite pumpy overall.","p16"],["77","La fissure rosse","The Nasty Crack","5c+","22 m","A nice journey up a crack. Big moves on good holds. Classy at the grade.","p16"],["78","Clones aux mains nues","Bare-Handed Clones","6b+","22 m","Complex — make sure to plan the line ahead. Very fun.","p16"],["79","Voyage au bout du surbac","Journey to the End of the Surbac","7a","22 m","Quite bouldery. Start on rock sculpted by water droplets; fun roof and mantel. Takes determination for the mantel.","p16"],["80","Le surplomb du siamois","The Siamese Overhang","6a","22 m","Surprising but very cool route at the grade.","p17"],["81","Atout cortex","Cortex Trump Card","6b","22 m","Variant of route 80, less physical but more technical and on slab. Plenty of smearing. Pretty, fun route.","p17"],["82","Le siamois de gauche","The Left Siamese","5c+","22 m","Inconsistent. Getting into the corner is the crux. Fun finish.","p17"],["83","Pets et vesses","Farts and Silent Farts","5a","22 m","Cracked slabs broken up by small ledges. Fun at the grade.","p17"],["84","L'ondulée","The Wavy One","4b","22 m","Pleasant climbing in a corner.","p17"],["85","Variante","Variant","5b+","22 m","Start up L'Ondulée to reach a wide crack on the left. Original.","p17"],["86","La fluette","The Slender One","5c+","22 m","Very nice route with varied styles. A must-do.","p17"],["87","Poussière d'étoile","Stardust","6b","22 m","Jamming technique to the fore… the art of the lock.","p17"],["88","La fissure des buis","The Boxwood Crack","5c","20 m","One slightly bouldery move. Route often overgrown with vegetation.","p17"],["89","Ménétrier","Fiddler","6c","20 m","Nice slab route. Unstable flake at the top — don't yank on it like an ox; go round it on the left.","p17"],["90","Dièdre jaune","Yellow Corner","4c","20 m","Corner climbing with bridging/opposition moves.","p17"],["91","Pour l'amour du rire","For the Love of Laughter","6b","15 m","Short, intense route on slightly dubious rock.","p18"],["92","La fleur","The Flower","6b+","15 m","Short, punchy route that needs real determination.","p18"],["93","Un seul ennui : bras et zézettes ramollissent","Only One Problem: Arms and Willies Go Soft","6c","22 m","Original line, big jugs and a traverse under a roof. Holds a bit dirty. Disconcerting route overall.","p18"],["94","Fissure des filles","The Girls' Crack","5b+","22 m","Route on surprising rock. Technical climbing.","p18"],["95","Trapco, mate pas trop les filles","Trapco, Don't Ogle the Girls Too Much","5c+","22 m","Technical slab.","p18"],["96","Nez de bœuf","Ox Nose","5c+","22 m","Starting variant of 99.","p18"],["97","Béret du guide","The Guide's Beret","5c+","22 m","Starting variant of 99.","p18"],["98","Boys zone","","5c+","25 m","Starting variant of 99.","p18"],["99","Spirale","Spiral","5c","25 m","Big traverse with an original line. Rope drag possible. Climbing it as a second is recommended to retrieve the quickdraws.","p18"]]},{"id":5,"name":"La Kir","gloss":"","color":"#139488","stats":{"routes":42,"grades":"5b – 7c","aspect":"South & East-facing","height":"25 m to 30 m"},"intro":"p19","warning":"SECTOR CLOSED from 15 February to 15 June — prefectoral biotope-protection order, because peregrine falcons nest here.","notes":["The routes on this sector are of exceptional quality.","Varied grades and climbing styles."],"topos":[{"page":"p20","routes":"100–106"},{"page":"p21","routes":"107–115"},{"page":"p22","routes":"116–127"},{"page":"p23","routes":"128–136"}],"routes":[["100","Les mains pleines de bérézina","Hands Full of Disaster","6b+","28 m","Sustained and consistent. Small roof with hidden holds. Athletic climbing that needs a bit of flexibility. One move where you'll have to commit.","p20"],["101","Bobologie","","7a+","28 m","Bouldery. One move where you'll need to have the sequence dialled. Demanding to read. Fairly pumpy overall.","p20"],["102","Kir","","7a","28 m","Sustained. A very good stamina test at the grade. Demanding, technical climbing. A must-do.","p20"],["103","L'ange choit","The Angel Falls","7b+","28 m","Sustained climbing. Very intense bouldery section, slightly reach-dependent.","p20"],["104","Top lisa","","7b","28 m","Physical, complex climbing. Very beautiful. Needs a good climbing rhythm and plenty of power.","p20"],["105","Deuxième inconnue","Second Unknown","6b","30 m","Start on the right and finish on the right. Follows the line of weakness; nice route with an original line.","p20"],["105-1","Fifi brin d'acier","Pippi Steel-Strand (pun on Pippi Longstocking)","6b+","30 m","Same start as 'Deuxième inconnue' but finish straight up. Nice technical slab at the top. Keep something in reserve for the finish.","p20"],["106","Jojo mets ta laine","Jojo, Put Your Sweater On","6b","30 m","Slightly disconcerting direct start. Finish in the crack of 'Deuxième inconnue'.","p20"],["107","Illusions trouvées","Found Illusions","6c+ / 7a","30 m","Consistent. Beautiful technical route on a gassy (exposed) pillar. Relaxing at the rests is the key to the redpoint. Atmospheric finish. Very classy — a must-do.","p21"],["108","Le fil à couper le beurre","The Butter-Cutting Wire","6a+ / 6b","30 m","Very sculpted rock. A route with character that demands commitment and determination.","p21"],["109","Le fil à plomb","The Plumb Line","6b","30 m","Starting variant of 'Le fil à couper le beurre'. Start up route 107, then traverse left.","p21"],["110","Réconciliation sur l'oreiller","Making Up on the Pillow","7a+","30 m","Fairly consistent. Beautiful moves; technical, slightly run-out climbing on the overhanging slab at the top.","p21"],["111","La rixe","The Brawl","6c+","30 m","Demanding climbing at the start, easier finish in the crack.","p21"],["112","Chang de la","","6c+","30 m","Mixed climbing, with a start that needs good route-reading. Middle section shared with 111. Finish by traversing right onto a slab. Original line.","p21"],["113","Le retour du phoque","Return of the Seal","6a","28 m","Consistent and very varied. Keep something in reserve for the finish. A beautiful route at the grade (careful not to bully the wedged block at the top).","p21"],["113-1","Le retour vers le futur","Back to the Future","6c","28 m","Not consistent; the scoop at the top is very sculpted. Belay attentively.","p21"],["113-2","L'eau tarie","Dried-Up Water","6b","28 m","Finish straight up via a sculpted crack. Committing finish.","p21"],["114","Le Pigeon à Odette","Odette's Pigeon","P1 5b / P2 5c","18 m / 30 m","Nice route but broken up by ledges. Possible anchor halfway. There is a bees' nest on the 2nd pitch: be careful.","p21"],["115","La guerre des buvettes","The Snack-Bar War","5c","30 m","Hard start on a pillar; joins the anchor of 114, or can also finish up 113-1 for more consistency.","p21"],["116","Un passager pour le futur","A Passenger for the Future","6b","30 m","Technical, Cormot-style slab that takes a bit of intuition…","p22"],["117-1","Tata Lulu","Auntie Lulu","5c","30 m","Fun route, finish up 117.","p22"],["117","Le facteur","The Postman","5b+","30 m","Historic route, varied styles. The summit chimney is surprising.","p22"],["118","La JP","","5c","28 m","Physical and consistent. Bridging/opposition in a flake. Mantels and corners that aren't easy to negotiate.","p22"],["119","Scènes de chaste","Chaste Scenes (pun on 'hunting scenes')","6b+","28 m","Finishing variant of 118. Sustained climbing on spaced flat edges at the top of the route.","p22"],["120","La JP directe","JP Direct","5c","30 m","Starts left of La JP. Awkward mantel onto the ledge.","p22"],["121","Jour blanc","Whiteout","5c+","30 m","Finishing variant of 120. Follow the line of the pillar, with a mantel that needs flexibility.","p22"],["122","Le Rambo des bacs à sable","The Sandpit Rambo","6c+","30 m","Pillar with varied climbing and holds. Nice crimpy slab at the top.","p22"],["123","Le villebrequin","The Brace Drill","5b+","30 m","Varied, unusual climbing. Surprising tufa column low down; the rest is really physical. Very nice route.","p22"],["124","Nuits secrètes","Secret Nights","6b","30 m","Complex to read. Technical route overall that needs good anticipation.","p22"],["125","Miracles ordinaires","Ordinary Miracles","7b","30 m","Bouldery route with a serious slab problem. Feet often on nothing much, but the route is no less interesting for it.","p22"],["126","La coupe","The Cup","7b+","30 m","Slab lovers will enjoy it. Bouldery route with big moves on sloping holds.","p22"],["127","Cholesterock'n roll","","7c","30 m","Inconsistent and very intense on the hard moves. A 'key' move on a concave slab on micro-holds.","p22"],["128","La chatière","The Cat Flap","6b","30 m","Curious slab start, then traverse right to reach a wide crack. Interesting climbing.","p23"],["129","Chatte en folie","Crazy Cat","6b+","30 m","Same start as 128, then finish in the small vertical crack. Finger climbing.","p23"],["130","Capitaine cradock","Captain Haddock (pun)","7a","30 m","Sustained climbing on flat crimps, sometimes a little spaced.","p23"],["131","Chic fissure","Chic Crack","5b+","30 m","Layback (Dülfer) climbing, a little physical on the hard move, where the polish starts to show. Rising traverse left to reach the big crack.","p23"],["132","Ric","","5c+","30 m","Not consistent, with many rests on the route. Bridging and crack climbing to the fore. A section of loose rock in the second half of the route.","p23"],["133","Les jeux des nuages et de la pluie","The Games of Clouds and Rain","6a+/b","30 m","Selective start, then a vertical crack and big flakes. Varied climbing.","p23"],["134","Aranéides","Spiders","6b","30 m","Direct start to route 132. Lacks consistency.","p23"],["134-1","L'année des pianos à queue","The Year of the Grand Pianos","7a","30 m","Sustained, varied and technical climbing.","p23"],["135","La partouze","The Orgy","6b+","30 m","Intense moves broken up by good rests; keep a bit in reserve for the finish.","p23"],["136","Le pilier de la burn's","","6c","30 m","Sustained and consistent. Overhanging slab on small holds and a pillar climbed with finesse.","p23"]]},{"id":6,"name":"La Troyenne","gloss":"The Woman from Troyes","color":"#e8582a","stats":{"routes":20,"grades":"5c – 7b+","aspect":"South & East-facing","height":"25 m to 30 m"},"intro":"p24","notes":["Varied grades and climbing styles on this sector.","Rock quality ranges from poor to exceptional."],"topos":[{"page":"p25","routes":"137–144"},{"page":"p26","routes":"145–155"}],"routes":[["137","Burn's","","6c+ / 7a","30 m","Sustained with good rests; difficulty increases and is varied. Both technical and physical.","p25"],["138","Croule Raoul","","6b+","30 m","Delicate slab livened up by a curious mantel onto a glued block. Unusual climbing.","p25"],["138-1","Tomo","","7a","30 m","Direct variant of 138 straight up the slab. Consistent and sustained overall.","p25"],["139","L'éclair","The Lightning Bolt","5c","30 m","Original line with successive traverses that give this route a unique character. (Possible start via 140: 5c+.)","p25"],["140","La dure réalité de la friction","The Harsh Reality of Friction","6a","30 m","Very nice route with fun tufa in the first part; some loose flakes at the top need care. A must-do!","p25"],["141","Luliberine","","6b","30 m","Finishing variant of 140 (trend slightly right after the horizontal band).","p25"],["142","L'éclair direct","Lightning Bolt Direct","6b/c","30 m","Not consistent; a slightly reach-dependent roof move, but pleasant nonetheless.","p25"],["143","Le cheval blanc aux oreilles bleues","The White Horse with Blue Ears","6c","30 m","Sustained, varied and surprising climbing. A rather sneaky Cormot-style pillar.","p25"],["144","La Simone","","6b","30 m","Varied climbing that needs good route-reading and good anticipation of the line. A classic.","p25"],["145","Bebe cadum","Cadum Baby (soap advert)","6c","30 m","Sustained. Needs good reading (some holds are hidden). Nice technical climbing in the first part; the rest is rather athletic on good holds.","p26"],["146","La Troyenne","The Woman from Troyes","6b+","28 m","Sustained, continuous and varied. Physical start on edges, then a slab all about balance, a corner and a fun mantel. Loose rock on the last 2 metres. Nice route.","p26"],["147","Les gars du bâtiment","The Building-Site Guys","7b+","28 m","Pump galore. Not easy onsight — reading and determination are essential weapons for this route. Very fun overhanging pillar.","p26"],["148","Valse sur peau de banane","Waltz on a Banana Skin","7a","28 m","Direct variant of 149. Bouldery. Demanding technical climbing.","p26"],["149","La romaine","The Roman","6b+/c","25 m","Route with an original line. Start with a traverse under a small roof, then a traversing line. The rock sometimes has no texture, so you have to squeeze the holds all the harder.","p26"],["150","Passage quaternaire","Quaternary Passage","6b","30 m","Finishing variant of 149. Traverse all the way left to finish on the left face. Move over a big wedged block, great atmosphere.","p26"],["151","Valium cassis","Blackcurrant Valium","6b+","30 m","Slightly bouldery but original route. The finish on the side of the prow may leave you with a few souvenirs.","p26"],["152","La Christine","","5c+","30 m","Traverses slightly left, on good holds. The rock is loose at the top — careful with some unstable blocks.","p26"],["153","La Vincendon","","6a","28 m","Historic but inconsistent route, broken up by ledges. Demanding and very aesthetic summit overhang.","p26"],["154","La guerre des clans","The Clan War","6b","28 m","Sustained, varied climbing. Sneaky, demanding exit slab. Slightly loose rock at the top below the anchor.","p26"],["155","Soie et velours","Silk and Velvet","6a","28 m","Starting variant of 153. Technical finger climbing.","p26"]]},{"id":7,"name":"La Voie de l'arbre","gloss":"The Tree Route","color":"#a8203f","stats":{"routes":13,"grades":"5c – 7c","aspect":"South & East-facing","height":"28 m to 32 m"},"intro":"p27","notes":["Rather physical climbing style on this sector.","Lots of roofs.","Good-quality rock.","Routes 168 to 173 (Le curé de Miraude + L'enfant de chœur, between sectors 7 and 8): bolting and cleaning pending — poor-quality rock."],"topos":[{"page":"p28","routes":"156–167"}],"routes":[["156","Mandragore","Mandrake","7a","28 m","Sustained with good rests; the difficulty is at the start in the roof. Both technical and physical climbing along the pillar. Very nice route. Do it onsight.","p28"],["157","Yaveka","","7b+","32 m","Very intense over the first three bolts, then pumpy. Fun route that needs strength.","p28"],["158","Le râteau","The Rake","6c+","30 m","Varied overall. Physical start; the slab that follows is rather technical. Nice route.","p28"],["159","Paix impossible, guerre improbable","Impossible Peace, Improbable War","7c","30 m","Sustained, continuous climbing. Fairly complex route — the onsight is far from a given — and keep a bit in reserve for the overhanging slab at the top.","p28"],["160-1","Racines","Roots","6c","30 m","Starting variant of 160. Sustained. Non-obvious slab on slopers. Makes 160 very consistent.","p28"],["160","La voie de l'arbre","The Tree Route","6b+","28 m","Crack climbing. Nice route with an original finish in the tree.","p28"],["161","Jambon - beurre","Ham & Butter (the classic French sandwich)","7b","30 m","Route that wanders through the roofs. Joins the crack of route 160 after the roof. Physical, very enjoyable climbing.","p28"],["162","Le balancier","The Pendulum","7b","30 m","Very athletic climbing that needs core strength and flexibility for the mantel. A must-do.","p28"],["163","Lumière du vide","Light of the Void","7b+","30 m","Finishing variant of route 162. Stay in the overhanging corner when exiting the roof. Physical and very enjoyable. Very exposed overall.","p28"],["164","La petite Mimiche","Little Mimiche","6a","28 m","Crack climbing with a traverse under the roof. Original.","p28"],["165","La Toto","","5c+","28 m","Start up a steep crack, then traverse left to reach the crack of route 167. Consistent and exposed overall.","p28"],["166","La Zizine","","5c","28 m","Athletic bridging/opposition moves in a crack.","p28"],["167","Compte de faits","Fairy Tale (pun: 'count of facts')","6b","30 m","Starting variant of 165. Very bouldery at the start, with very original moves.","p28"]]},{"id":8,"name":"Vieille maîtresse","gloss":"Old Mistress","color":"#46b3c4","stats":{"routes":21,"grades":"4b – 7b+","aspect":"South-West-facing","height":"20 m to 30 m"},"intro":"p29","notes":["Sector with fairly demanding starts.","Sector that stays sunny for a long time despite the trees.","Rock of variable quality, but decent overall."],"topos":[{"page":"p30","routes":"174–183"},{"page":"p31","routes":"184–193"}],"routes":[["174","La cheminée de l'enfant de chœur","The Choirboy's Chimney","4b","20 m","Easy route in a wide chimney (old descent route); chimneying technique may come in handy. Unstable blocks — be vigilant.","p30"],["175","La Bob","","5c","20 m","Surprising, mixed route. Steps, then a nice slab.","p30"],["176","Le Groseiller","The Currant Bush","5a","25 m","Slightly polished classic. Two technical moves in a corner. Fun overall.","p30"],["176-1","Marietou","","6a+","27 m","Pleasant overall on good jugs.","p30"],["177","Le Domino direct","Domino Direct","6a+/b","30 m","Starting variant of 178. Athletic in a wide crack. Intense start.","p30"],["178","Le Domino","","6a+","30 m","Sustained, vertical climbing. Nice, really physical route on good holds.","p30"],["179","Gorillodrome","","7b+","30 m","Varied route. Slightly nasty start, rock with loose flakes after that, and a nice slab of sloping pockets to finish. Mixed, but very fun all the same.","p30"],["180","Gros bras et jambettes","Big Arms and Little Legs","7a+","30 m","Consistent, technical finger climbing. A must-do.","p30"],["181","Le passe muraille","The Man Who Walked Through Walls","7a","30 m","Major route at the grade. Intense start on edges and water drips, followed by a crack in very sculpted rock. Fairly pumpy overall.","p30"],["182","Vieille maîtresse","Old Mistress","6b+","30 m","Sustained, pleasant climbing.","p30"],["183","Trans zen 10","","7a","30 m","Intense start on an overhanging pillar that needs careful reading beforehand. The second part is less intense but technically demanding.","p30"],["184","L'Armir","","6b","27 m","Nice consistent route — a must-do.","p31"],["185","Les hommes préfèrent les bombes","Men Prefer Bombshells","6c/6c+","27 m","Mixed route. A series of small slabs with technical problems, broken up by good rests.","p31"],["186","La BAF","","6a+","27 m","Consistent but not very sustained. Rather balance-oriented in the first part, followed by a traverse right at the niche on good edges. Fun.","p31"],["187","La BAF directe","BAF Direct","6a+","27 m","Finishing variant of 186. Straight up above the niche. Fingery.","p31"],["188","Beauté cachée","Hidden Beauty","6a","27 m","Consistent, technical slab climbing. Nice big moves. Tends to be run-out.","p31"],["189","Banana slip","","5c+ / 6a","25 m","Finishing variant of 188. Nicely consistent. Steep, technical slab.","p31"],["190","Que dalle","Zilch (pun on 'slab')","6c","25 m","Bouldery. Slab with spaced holds at the start, then a rest, then a thin flake and a demanding compact slab.","p31"],["191","Hyperbole","","5c+","30 m","Traversing route with an original path. Committing and unusual. Not the most interesting at the grade.","p31"],["192","Liturgie cathodique","Cathode Liturgy","6a","25 m","Consistent, sustained and demanding route. Crimps on a slab to tame. There is a bees' nest at the time of writing.","p31"],["193","L'éloge de la fuite","In Praise of Running Away","6a","25 m","Finishing variant of 192. A demanding boulder move to leave the niche.","p31"]]},{"id":9,"name":"Le Boulevard à Mathieu","gloss":"Mathieu's Boulevard","color":"#5a8a2c","stats":{"routes":15,"grades":"4c – 7c+","aspect":"South-facing","height":"20 m to 30 m"},"intro":"p32","notes":["Sector with very compact rock and a few flutings (runnels).","Vertical slab with technical, demanding climbing on crimps."],"topos":[{"page":"p33","routes":"194–200"},{"page":"p34","routes":"201–206"}],"routes":[["194","L'escalier","The Staircase","4c","20 m","Easy route along a flake. Climbing on jugs, but it still needs good technique.","p33"],["195","Fréquence tendresse","Tenderness Frequency","6a+","25 m","Very nice route on pretty, well-sculpted rock.","p33"],["196","Le caprice des vieux","The Old-Timers' Whim","6b","25 m","Finishing variant of route 195. Very sculpted rock. Continuous and consistent overall.","p33"],["196-1","Swiss connection","","7a","25 m","Complex route where you'll have to pinch hard. Demanding foot placements on very sculpted rock. Bouldery but very fun.","p33"],["197","Le Boulevard à Mathieu","Mathieu's Boulevard","7a+/b","25 m","A great classic on fantastic rock. Concretions that sometimes lack texture force you to squeeze the holds hard. A beautiful onsight prospect.","p33"],["198","Le pro s'tâte","The Pro Hesitates (pun on 'prostate')","7c+","25 m","Finishing variant of route 197. A boulder problem on micro-holds.","p33"],["199","Le champ du Perfodactyle","The Field of the Perfodactyl","6c+","30 m","Consistent route on crimps. A classic at the grade.","p33"],["199-1","Le champ du Perfodactyle direct","Perfodactyl Field Direct","7b","30 m","A serious boulder move on slab.","p33"],["200","Zargo's lords","","6b+","30 m","Very nice route on sometimes 'dubious' rock; very interesting and varied line.","p33"],["201","Bossu fait gaffe à l'orage","Hunchback, Watch Out for the Storm","7b+","30 m","Slab problems. Climbing on small flakes. Technical.","p34"],["202","Gémis sans mollir","Moan Without Weakening","7b","30 m","A slab move leads to an athletic crack. Not the best route at the grade.","p34"],["203","L'Ionisation","Ionisation","6b+","30 m","Varied, physical and rather athletic climbing. Start up the slab alongside the cave, then a steep section on good holds.","p34"],["204","Radio chou-fleur","Radio Cauliflower","6c","27 m","Finishing variant of route 205. Very nice ending.","p34"],["205","La facilité","The Easy Way","6c","27 m","Technical climbing in the first part, then really physical in the second.","p34"],["206","Eclipse de bras","Arm Eclipse","6c+","27 m","Similar to route 205, sharing the central section.","p34"]]},{"id":10,"name":"Robert clef de 12","gloss":"Robert the 12 mm Spanner","color":"#9c1d1d","stats":{"routes":24,"grades":"5b+ – 8a","aspect":"South-facing","height":"30 m to 35 m"},"intro":"p35","notes":["The canyon sector: shady, nice on very hot days.","Climbing is often vertical or even slightly overhanging.","Physically demanding climbing."],"topos":[{"page":"p36","routes":"207–212"},{"page":"p37","routes":"213–220"},{"page":"p38","routes":"221–227"}],"routes":[["207","La Bambino","","6a+","32 m","Very nice, physical route. One move that is very demanding on core strength for the grade. Crack climbing on jugs and big pockets — you climb through the jackdaws' nests.","p36"],["208","Le pilier d'étrons","The Pillar of Turds","6b","30 m","Finishing variant of 207. A very fun, airy diagonal ramp.","p36"],["209","Ben Hur descends de ton youpala","Ben Hur, Get Out of Your Baby Walker","7c","30 m","Climbing on rock that is more solid than it looks in the first part. Slightly steep pillar at the top that requires climbing with rhythm.","p36"],["209-1","Câlin express","Express Cuddle","7c+","32 m","Bulges that are hard to negotiate.","p36"],["209-2","La Jean Phi","","8a","32 m","Start up 210, then the same finish as Câlin express. Nice route that requires a well-paced, rhythmic climb.","p36"],["210","La Mondette","","6c+","35 m","Named after the landlady of the Saffres bar, back when there was one. A great journey with an intense boulder move.","p36"],["211","Splendeur sauvage","Wild Splendour","7a","32 m","Straight up the steep ground. Very nice route where you need to manage the rests well — a beautiful onsight to do, but not a given. A Saffres staple.","p36"],["212","Topoverdose","","6b+","32 m","Technical, varied route — one of the crag's classics at the grade.","p36"],["213","Ygdrasil","Yggdrasil","7b+","32 m","Very nice, continuous and really pumpy route. Pillar that demands a strong sense of route-reading.","p37"],["214","La Quille","The Skittle","6c+","32 m","Mixed route with an easier section in the middle. Save some energy for the top moves, which need strength and real determination.","p37"],["215","Robert « clef de 12 »","Robert 'the 12 mm Spanner'","6c+","32 m","Consistent, fairly complex route that needs technique and good route-reading. A must-do.","p37"],["216","La Terray nouvelle","The New Terray","7a","32 m","Sustained climbing with an intense move on a hard-to-hold sloper mid-route; the rest is really pumpy and very pretty.","p37"],["217","L'aspic","The Asp","6a","30 m","Route with an original line. Physical start on edges, a slightly unsettling traverse right and an easier finish in a corner. Slightly loose rock that needs care.","p37"],["218","Le Beauf","The Redneck","6a","30 m","Very bouldery, with one move where you'll have to get angry. Easier exit crack.","p37"],["219","La Pépère","The Easy-Going One","5b+","30 m","Easy route that needs good anticipation of the line. Some ledges break the rhythm.","p37"],["220","Inox du sol au plafond","Stainless Steel from Floor to Ceiling","5c+","28 m","Steep start on jugs, a section shared with route 218. Mixed route.","p37"],["221","Touche pas à mon spit","Hands Off My Bolt","6c+","28 m","Surprising, bouldery route. 3 boulder-style sections broken up by ledges. Not the most interesting at the grade.","p38"],["222","Tintin au pays des écailles","Tintin in the Land of Flakes","7b","28 m","Slab lovers will be happy here. Profile somewhat like route 221. Bouldery sections broken up by good rests. Smearing and balance to the fore.","p38"],["223","RSCM 78","","5c+","30 m","Starting variant of 224. More direct crimpy slab.","p38"],["224","La plus belle fissure","The Most Beautiful Crack","6a","30 m","Fairly demanding crack climbing. A route that needs good jamming and bridging technique. A band of loose rock in the first part — be careful.","p38"],["225","La Caporal","The Corporal","6c","30 m","Very pleasant route on very beautiful, well-sculpted rock.","p38"],["225-1","A38 again","","6c+","30 m","Finishing variant of route 225. Exit through a steep section with hidden holds; very enjoyable climbing.","p38"],["226","Le sens de l'histoire","The Direction of History","7a+","30 m","Sustained and continuous. Very nice route with a nasty start and great atmosphere at the top.","p38"],["227","Edelridissimo","","7a","30 m","Varied route with steep ground, slab and crack. A route for all-round climbers. Exposure in the second part of the route.","p38"]]},{"id":11,"name":"Magie blanche","gloss":"White Magic","color":"#155a99","stats":{"routes":18,"grades":"5b – 7b","aspect":"South-West-facing","height":"30 m to 35 m"},"intro":"p40","notes":["Sector with rather continuous, very vertical climbing.","Sun from mid-morning.","Fairly shady at the base thanks to the trees."],"topos":[{"page":"p41","routes":"227-1–230"},{"page":"p42","routes":"231–236"},{"page":"p43","routes":"236-1–240"}],"routes":[["227-1","Indiana JMB","","7a+/b","30 m","Complex to read. Climbing on dubious, really pumpy flakes; keep a bit in reserve for the finish. Sustained overall.","p41"],["228","La pivoine","The Peony","6c","30 m","Very continuous up to the horizontal band. Economy and speed are good weapons for this route. A route with character. Very fun.","p41"],["228-1","Tonton inox","Stainless Uncle","7a","30 m","Difficulty concentrated at the start. Technical footwork. Reading is essential.","p41"],["229","Magie blanche","White Magic","6b+","32 m","Very continuous route that needs a good analysis of the line. Often physical climbing that needs good management of the rests. A staple at the grade.","p41"],["230","L'arrachée","The Snatch","5c","32 m","Really vertical climbing on jugs. A treat.","p41"],["231","Les coups et les douleurs","Blows and Pains (pun on 'colours')","6c","32 m","Continuous climbing with a hard move in the 2nd part. The summit wall is complex to decipher. Somewhat mixed route.","p42"],["232","Le mètre déplié","The Unfolded Ruler","5c","30 m","Very fun route on very sculpted rock. Athletic climbing on good holds.","p42"],["233","Dis, l'auvergne saoud ?","","6b","30 m","Inconsistent but varied. Funny overhang with a nice cluster of holds.","p42"],["233-1","Fin de siècle","End of the Century","7a","30 m","Finishing variant of 233. Short but intense. An overhanging slab with crimps and a blocked crack on the menu.","p42"],["233-2","Trivial merdic","","6b+","32 m","Left finishing variant of 233. Athletic, with a nice variety of sometimes surprising holds.","p42"],["234","Le mètre pliant","The Folding Ruler","P1 5a / P2 5c","20 m / 35 m","The first pitch is short, on beautiful rock with plenty of vertical cracks. The second pitch is an airy traverse under a band of overhang, on rock that is sometimes a little polished.","p42"],["235","La marc","","6a","30 m","A very beautiful route at the grade. Stunning atmosphere at the top with a great variety of moves.","p42"],["236","Bourbon's club","","6b","30 m","Same profile as 235 with less obvious holds. Good lock-offs; a nice, really physical route.","p42"],["236-1","Calinette","","7a+","30 m","Nice bouldery route.","p43"],["237","Satyre","Satyr","7a","30 m","Route through a small overhang, one very bouldery move. Lacks consistency.","p43"],["238","Satan","","6b","30 m","Very nice, varied route that needs good pacing. Awkward positions give this route a unique character.","p43"],["239","Le piano à queue","The Grand Piano","5b+","32 m","Slightly polished corner route. After the ledge, branch left; belay attentively because of the ledges.","p43"],["240","Le piano droit","The Upright Piano","5c","30 m","Same start as route 239, then continue up the cracked slab straight above. Very beautiful.","p43"]]},{"id":12,"name":"Damoclès","gloss":"Damocles","color":"#8f8478","stats":{"routes":21,"grades":"5a – 8b","aspect":"South-facing","height":"25 m to 32 m"},"intro":"p44","notes":["Sector with very compact rock.","Alternating small corners and pillars.","Rock colour ranges from yellow through grey to blue.","Often physical climbing on vertical to slightly overhanging profiles.","Shady at the base."],"topos":[{"page":"p45","routes":"241–252"},{"page":"p46","routes":"253–260"}],"routes":[["241","Les pantoufles de l'aventure","The Slippers of Adventure","6a","30 m","Sustained and varied. The route starts by traversing left, with lots of pinches. The exit pillar is really airy.","p45"],["242","La dalle ocrée","The Ochre Slab","5b","30 m","Slab with big holds at the start and a traverse right (crosses route 241). Then follows the line of the pillar. Very fun route.","p45"],["243","La lupa","","5c","30 m","Continuous route in an overhanging yellow corner. Athletic climbing on jugs. After the ledge, take the back of the corner.","p45"],["244","Lupanard","","5c","30 m","Same start as the previous route, with a finish where you must stay on the arête of the slab.","p45"],["245","La gifle","The Slap","6b+/c","28 m","Inconsistent climbing. The 1st part is very easy on big holds; then a bouldery section on a grey slab with small crimps needs flexibility, grip and determination.","p45"],["246","Le flambeau direct","The Torch Direct","6a+","28 m","Varied route. Slab start on edges, then a demanding corner and an easier finish. Fairly sustained overall.","p45"],["247","Ultimatum uranium","","6c","28 m","A natural hive regularly occupied (bees!) on the upper slab. Magnificent route on beautiful rock. Physical, technical and slightly committing climbing in the 2nd part. A must-do.","p45"],["248","Le Flambeau","The Torch","5c+","32 m","Traversing line, as was fashionable in the '80s. Climbing on good holds broken up by ledges.","p45"],["249","Terminator","","6c+","25 m","Sustained, fairly physical climbing on steep ground. A classic at the grade. Very nice, really pumpy route.","p45"],["250","Le petit déjeuner","Breakfast","7b","27 m","One of the most beautiful routes on the crag. An absolute must-do. It has everything: steep ground, good holds, plenty of technical moves, demanding to read — in short, a staple!","p45"],["251","Damoclès","Damocles","7a","27 m","Steep climbing following a sometimes blocked crack. Demanding to read. Varied, very pleasant climbing. A must-do, one of the most beautiful at the grade.","p45"],["252","Le balayeur de mots","The Word Sweeper","6b+","27 m","Technical climbing on a pillar. Awkward start on a slightly overhanging pillar, then a slab with deceptive holds, easier finish. Nice route.","p45"],["253","Le beau vélo de Ravel","Ravel's Nice Bike","5c","27 m","Inconsistent climbing. Very rough rock, cracks that need good control. Some ledges break the rhythm.","p46"],["254","Les dégonflés","The Chickens (lit. 'the deflated')","5b+","27 m","Starting variant of route 253. Slabs with good holds. Fun overall.","p46"],["255","La montagne Directe","The Mountain Direct","5a","27 m","Starting variant of 256.","p46"],["256","La montagne","The Mountain","5a","27 m","A great classic of the crag. Polished route that still needs care to avoid a slip. Historic route, as it was one of the first climbed free.","p46"],["257","Sitiger","","6a+/b","27 m","Sustained and varied climbing. Corner slightly polished because it is sheltered from rain; technical, complex climbing on very demanding crimps. Committing at the overhang. A benchmark route at Saffres — a good test of your level.","p46"],["258","Issue de secours","Emergency Exit","6a+","25 m","Finishing variant of route 257. Traverse right after the leaning slab to reach a small, slightly physical overhang. Fun route.","p46"],["259","La Montreuil","","8b","30 m","Overhanging slab with a saving sloper. A big dynamic move towards the top. 'Old-school' technical climbing.","p46"],["259-1","No passaran","","7c+","30 m","Same line as route 259 lower down, then avoids the hard move on the left. Same finish. Very classy overall. A must-do.","p46"],["260","Calamity bedi","","6c","30 m","Sustained overhanging route with a good rest. Finishes along the arête with a nice flight up jugs.","p46"]]},{"id":13,"name":"Sans nom","gloss":"Nameless","color":"#6b2f7d","stats":{"routes":39,"grades":"4a – 6c","aspect":"South & East-facing","height":"5 m to 25 m"},"intro":"p47","notes":["Small, shady sector with some slightly polished routes.","Some very interesting bouldery moves.","The base of the routes is not always very comfortable."],"topos":[{"page":"p48","routes":"261–268"},{"page":"p49","routes":"269–277"},{"page":"p50","routes":"278–285-1"},{"page":"p51","routes":"286–292"},{"page":"p52","routes":"293–299"}],"routes":[["261","La marguerite directe","The Daisy Direct","6a+","25 m","Cracked pillar followed by a slab climbed with finesse.","p48"],["262","Rock zoulou","Rock Zulu","6a","25 m","Rhythmic climbing where you'll need to find the right tempo.","p48"],["263","La mort subite","Sudden Death","6a","20 m","Technical slab climbing.","p48"],["264","La marguerite","The Daisy","5b/c","30 m","Historic route first climbed between 1930 and 1940. Traversing line; can be done in 2 pitches to limit rope drag.","p48"],["265","L'examen","The Exam","6a+","23 m","Short, technical slab.","p48"],["266","La sorcière","The Witch","5c+","25 m","Physical start in a crack, then a slight traverse left. Careful not to fall into the tree.","p48"],["267","Coco bel œil","Coco Pretty-Eye","5b","10 m","Easy, fairly short route.","p48"],["268","Coco","","4c","20 m","Easy.","p48"],["269","L'endormi","The Sleepy One","5b+","20 m","Delicate starting move. Fun finish.","p49"],["270","La vedette","The Star","5c","20 m","Good cracks.","p49"],["271","Cathy","","5c","20 m","Delicate slab. The hard move is polished.","p49"],["272","Fanny","","5c","20 m","Technical slab move. Polished.","p49"],["273","La sans nom","The Nameless One","5b","18 m","Intense overhanging corner at the start, then easier. Tends to be polished.","p49"],["274","Sketchup","","4c","18 m","Finishing variant of 275.","p49"],["275","La pseudo","The Pseudo","4c","18 m","Slab then polished corner. Loose rock at the top.","p49"],["276","Le Graphos","","5a","18 m","Delicate corner.","p49"],["277","La Crunch","","5c","18 m","Corner then slab.","p49"],["278","Le bloc","The Block","4c","18 m","Slab on the side of a leaning block — fun.","p50"],["279","Nid de bœufs","Oxen's Nest","5a","18 m","Chimney crack.","p50"],["280","Histoire de conque","A Tale of a Scoop","6c","15 m","Beautiful concave scoop in compact rock; bouldery.","p50"],["281","La cathyverno","","6b","15 m","Small corner, then an overhanging pillar.","p50"],["282","Le censeur","The Censor","4c","15 m","Easy, interesting corner.","p50"],["283","L'écaille","The Flake","4c","15 m","Big flake and corner.","p50"],["284","La fée des doigts","The Finger Fairy","5b+","12 m","Slab move.","p50"],["285","Les nouilles à Jacquot","Jacquot's Noodles","4b","12 m","Staircase.","p50"],["285-1","Scoobi-doo","Scooby-Doo","5c","12 m","Technical slab climbing.","p50"],["286","Le dévissage","The Unscrewing (climber's slang for a fall)","4b","12 m","Chimney-corner, often dirty.","p51"],["287","La valse des pantins","The Puppets' Waltz","6c","12 m","Slab with small holds.","p51"],["288","La miaou","The Meow","6a","12 m","Slightly overhanging slab with pockets.","p51"],["289","Gipsy","","4c","10 m","Jugs.","p51"],["290","Tuyau de poêle","Stovepipe","4a","8 m","Chimney.","p51"],["291","Graine de bison","Bison Seed","4b","8 m","Cracked slab.","p51"],["292","Petzl","","4b","8 m","Arête.","p51"],["293","Rétro laser","","4b","8 m","Slab with a ledge.","p52"],["294","Sur les pieds","On Your Feet","4a","8 m","Staircase corner.","p52"],["295","Petit tonnerre","Little Thunder","5b","8 m","Vertical corner.","p52"],["296","Rantanplan","","4c","5 m","Staircase arête.","p52"],["297","Bulle et burille","","4a","5 m","Slab with big steps.","p52"],["298","Trompette","Trumpet","5b","5 m","Overhanging scoop and corner.","p52"],["299","Pic nic","Picnic","4c","5 m","Overhanging corner.","p52"]]},{"id":14,"name":"Grand Steak","gloss":"","color":"#e3201b","stats":{"routes":21,"grades":"4a – 7a","aspect":"West-facing","height":"8 m to 25 m"},"intro":"p53","notes":["Sector currently being cleaned and re-bolted.","Small sector with sometimes abrasive rock.","Uncomfortable ground at the base of the routes.","Rarely visited sector.","Some grades are still to be confirmed (shown as '?').","Short, nasty climbing."],"topos":[{"page":"p54","routes":"300–307"},{"page":"p55","routes":"308–320"}],"routes":[["300","Violette bleue","Blue Violet","4b","8 m","Slab, often mossy.","p54"],["301","Droz erra","","6a","15 m","Slab arête.","p54"],["302","K2","","6c","15 m","Overhanging slab, smooth, then less steep and easier.","p54"],["303","Le D","","7a","15 m","Faint corner.","p54"],["304","Kin top","","6c","15 m","Vertical corner.","p54"],["305","Grand steack","","6b+","18 m","Sculpted corner.","p54"],["306","BIP BIP","Beep Beep","6c","18 m","Scoop in rounded rock.","p54"],["307","Flot de parole","Flood of Words","7a","18 m","Overhanging slab.","p54"],["308","Rone","","6c","18 m","Overhanging slab at the finish.","p55"],["309","Vincent","","6a","18 m","Slab arête with big holds.","p55"],["310","Ailez","","4c","15 m","Leaning slab.","p55"],["311","Zotres","","4c","15 m","Leaning slab.","p55"],["312","Yakari","","5b","18 m","Overhanging slab broken up by ledges.","p55"],["313","Pluto","","5a","18 m","Crack, then steps.","p55"],["314","Papooses","","5a","20 m","Big crack, then slab.","p55"],["315","Pitchoune","Little One","6a","20 m","Bulge, then scoop.","p55"],["316","Symphonia","","6a+","20 m","Vertical slab with small holds, then flakes.","p55"],["317","Nirvana","","?","20 m","Thin slab, overhang and slab.","p55"],["318","Keraban","","?","23 m","Flared corner and overhang.","p55"],["319","Bosse fort","Work Hard (pun)","?","23 m","Finishing variant of 318. Vague overhanging corner.","p55"],["320","Arabesque","","?","23 m","Slab, overhang, pillar.","p55"]]},{"id":15,"name":"Tour Carrée","gloss":"The Square Tower","color":"#f2b51c","stats":{"routes":42,"grades":"4c – 7c","aspect":"All four faces","height":"30 m to 35 m"},"intro":"p56","notes":["A remarkable, emblematic sector of the Saffres cliff.","A rock tower about thirty metres high, detached from the main wall.","All 4 faces of the tower are bolted; their different orientations let you play with the sun.","Rock quality varies a lot depending on the face, so always stay vigilant.","Route numbers restart at 1 on this tower."],"topos":[{"page":"p57","routes":"1–10"},{"page":"p58","routes":"11–23"},{"page":"p59","routes":"24–33"},{"page":"p60","routes":"34–42"}],"routes":[["1","La Batier","","4c","30 m","The tower's normal route. Old descent route of the tower. Route with good jugs, some of which are not solid. Don't yank on them like an ox, or you'll see big blocks fall.","p57"],["2","Papy Russe","Russian Grandpa","5b","30 m","Easy route with a slightly bouldery start on good crimps. Needs good reading in the first moves.","p57"],["3","L'Equinoxe","The Equinox","5c+","30 m","Demanding climbing that needs good reading.","p57"],["4","Chaussettes jacquart","Argyle Socks","5b+","30 m","Fun slab climbing; some areas of slightly loose rock.","p57"],["5","Bobi","","5b","30 m","Varied climbing with a slightly physical slab move. Plenty of ledges — belay carefully.","p57"],["6","Idées Noires","Dark Thoughts","5b+","30 m","Starting variant of route 5.","p57"],["7","Oui nide iou","We Need You","5b+","30 m","Fun slab climbing; watch the solidity of some holds.","p57"],["8","Un âne pour la nuit","A Donkey for the Night","5b+","30 m","Some technical sections. Mainly slab climbing.","p57"],["9","Chaud Devant","Hot Stuff Coming Through","6a","30 m","Technical and sustained. A start that sets the tone, followed by a mantel onto a big flake. The finish along the arête is gorgeous and really airy.","p57"],["10","Le spigolo Nord-Ouest","The North-West Arête","5c+","30 m","Surprising climbing with atmosphere. Remember to extend some quickdraws to avoid rope drag.","p57"],["11","At Home","","6b+","30 m","Very complex starting pillar. Rather bouldery climbing where you'll have to optimise your reading. 2nd part is a walk.","p58"],["12","Bedoul la roumoule","","5c","30 m","Demanding start in a small, awkward corner; the rest is calmer but a little committing.","p58"],["13","DWD","","5c","30 m","A series of slabs in varied styles; joins route 12 at the top. Tends to be run-out.","p58"],["14","La Directissime","The Directissima","5c","30 m","A great classic. Climbing that needs intuition, good line management and good slab technique. A must-do.","p58"],["15","La perpendiculaire","The Perpendicular","6b+","30 m","Very technical, fingery climbing in the first part. 2nd part, after the ledge, on very sculpted holds.","p58"],["16","Pervers Pépère","","6b+","30 m","Same start as 15, then finish right into route 17 in a pleasant yellow hollow.","p58"],["17","L'innominata","The Unnamed One","6a+","30 m","Very technical climbing with a demanding move that takes determination. Magnificent.","p58"],["18","Age Quod Agis","Do What You Are Doing (Latin)","6a","32 m","Inconsistent climbing with plenty of ledges. The rock at the top is surprising.","p58"],["19","Concerto pour omoplates","Concerto for Shoulder Blades","6b","32 m","Inconsistent but very interesting. Really physical start and an exceptional finale on jugs.","p58"],["20","T'as pas cent balles","Got a Hundred Francs?","6a","32 m","Nice overhanging corner at the start followed by a technical slab. Possible finish via the overhang of route 19 after the ledge, trending left.","p58"],["21","La Ouest","The West","5c+","32 m","A big route with lots of variety. For the all-round climber.","p58"],["22","Un bus pour l'enfer","A Bus to Hell","6c+","32 m","Crimpy slab with some really nasty moves; finish up 23.","p58"],["23","Un bus direct pour l'enfer","A Direct Bus to Hell","6b+","32 m","A classic to do. Varied climbing along the line of a pillar mixing technique, power and good reading to top it all off. A must at the grade.","p58"],["24","La voie Allain","The Allain Route","6b","32 m","Selective start on a pillar, followed by an easier section, then a very pleasant finish in an overhanging crack.","p59"],["25","Nouvelles de l'enfer","News from Hell","6b/b+","32 m","Starting variant of route 24, with a nastier start.","p59"],["26","Éclair de Lune","Moonbeam","6a+","32 m","Starting variant of route 27. Physical climbing.","p59"],["27","Les Aigles","The Eagles","5c+","32 m","Athletic and absolutely beautiful climbing at the grade. Your strength is put to the test on this route. A slightly clumsy start, but the rest is well sculpted. A must-do.","p59"],["28","La Jo","","6b+","32 m","Same start as 27. Varied climbing with a first part in a crack on sometimes slightly dubious rock, followed by a second part where you need to pace your climbing well, on decent holds. Fun route.","p59"],["29","Falco Peregrinus","Peregrine Falcon","6c+","30 m","Technical climbing on rock with loose flakes.","p59"],["30","Les cent jours","The Hundred Days","6c","30 m","Start on very sculpted rock, then traverse left at the overhang to reach route 29; climbing on slightly 'crumbly' rock that doesn't inspire confidence.","p59"],["31","L'Échelon sauvage","The Wild Rung","7b+/c","30 m","Complex overhanging route. An unsettling traverse left on sometimes dubious rock. A nice route all the same.","p59"],["32","Icare, mon cousin","Icarus, My Cousin","7b+","30 m","Stunning route with a series of small roofs mixing grip, crack locks and core strength. A consistent, fun route that's worth a visit.","p59"],["33","Thalassa","","6c+","30 m","Jugs on steep ground. Nice route. A small thought for Georges Pernoud (TV presenter of the sea show 'Thalassa'). Apparently you can see the sea from the anchor.","p59"],["34","Les Pions","The Pawns","6b+","28 m","Nice physical route on good holds.","p60"],["35","Dimension Sacrée","Sacred Dimension","6c","28 m","Finishing variant of route 34. Bouldery mantel and a summit slab climbed with finesse.","p60"],["36","Carabinier","","5c+ / 6a","28 m","A historic route on surprising rock. Some slightly powerful moves mid-route. Good reading and precision are needed for the redpoint.","p60"],["37","État de Grâce","State of Grace","6b+","28 m","Finishing variant of route 36. Nice technical, compact slab.","p60"],["38","Ribouldingue","","7a","25 m","Fun slab route with some hidden holds.","p60"],["39","La Gus","","6b+/c","25 m","Nice, very technical slab route where a good sense of the line is essential.","p60"],["40","La Popof","","6a+","28 m","Pleasant route on good holds. A bit physical in places. A must-do.","p60"],["41","Shunt","","6a+","28 m","Starting variant of 40.","p60"],["42","Le Spigolo Nord Est","The North-East Arête","5c","28 m","Really vertical climbing on good holds. A complex move to get onto the slab.","p60"]]},{"id":16,"name":"Tour Penchée","gloss":"The Leaning Tower","color":"#0f6b4f","stats":{"routes":28,"grades":"4c – 8a","aspect":"Several faces","height":"5 m to 30 m"},"intro":"p61","notes":["Rarely visited sector, away from the crowds.","Short, bouldery climbing on often overhanging rock, ranging from poor to exceptional quality.","Unusual climbing.","Some routes are sheltered from the rain.","Route numbers restart at 1 on this tower."],"topos":[{"page":"p62","routes":"1–13"},{"page":"p63","routes":"14–24"},{"page":"p64","routes":"25–28"}],"routes":[["1","L'escargot","The Snail","6b","25 m","Leaning slab on a somewhat austere face.","p62"],["2","La voie Dalmais","The Dalmais Route","4c","25 m","The tower's normal route; easy but earthy. Not the most interesting at the grade.","p62"],["3","Gonopote","","5c","22 m","Sustained, fingery first part. A really technical leaning slab.","p62"],["4","Le Dièdre Inversé","The Inverted Corner","5a/b","20 m","Big lying-down corner allowing a great rising traverse on jugs. Surprising and fun overall.","p62"],["5","L'été meurtrier","One Deadly Summer","6a","22 m","Disconcerting climbing crossing two corners. A must-do.","p62"],["6","L'Obélix","Obelix","6b","18 m","Climbing on good holds on steep ground.","p62"],["7","Ô toi mon toi haut","O You, My High Roof (pun)","6c+","22 m","Finishing variant of route 5. Nice, surprising route.","p62"],["8","Touche pas à mon poète","Hands Off My Poet","7b","18 m","Varied, very interesting climbing that demands strength and determination right to the anchor.","p62"],["9","Le retour de King Kong","The Return of King Kong","7c+","15 m","Bouldery climbing. Core tension and compression on the programme.","p62"],["10","Tout feu tout femme","All Fire, All Woman","7b+","10 m","Continuous, complex overhang; rock sometimes crumbly.","p62"],["11","Culotte de Plomb","Lead Knickers","7a+","8 m","Overhang on bands that aren't always easy to use well. One big boulder problem.","p62"],["12","Le vice du dévers","The Vice of Overhangs","7b","15 m","Traversing overhang that visits every route exit on the face. Poor rock.","p62"],["13","Hip hop","","6a+","5 m","No interest (bolts removed).","p62"],["14","Homosapiens connardus","","5c","10 m","Route on good holds, traversing slightly left.","p63"],["15","Par mon...et par vos...","","6b+","30 m","A nice traverse that deserves a visit. Joins every anchor on the face.","p63"],["16","La diagonale du poux","The Louse's Diagonal","6b","30 m","Another traverse with an original path.","p63"],["17","Quadrillage","Grid","6a+","15 m","Fun route on good holds, a bit physical.","p63"],["18","Douce promenade","Gentle Stroll","6a","25 m","Traversing route following a good diagonal step. Shared finish with 21 and 23.","p63"],["19","La bonté du diable","The Devil's Kindness","6b","18 m","Climbing on astonishing rock bands. Fun route.","p63"],["20","Noctambule","Night Owl","6b+","18 m","Start from a block on the ground, then a slightly overhanging slab striped with thin cracks.","p63"],["21","La vampire","The Vampire","6a","20 m","The first route bolted on the leaning tower. Surprising climbing on a slight rising traverse. A must-do.","p63"],["22","Pas de prises, pas de surprises","No Holds, No Surprises","7a+/b","20 m","Fingery slab with an easier finish.","p63"],["23","Le centimètre","The Centimetre","6c","20 m","Finishing variant of route 22.","p63"],["24","Obsession inoxydable","Stainless Obsession","7?","20 m","Technical and fingery.","p63"],["25","Chronique d'une chute annoncée","Chronicle of a Fall Foretold","8a","20 m","Technical, varied climbing.","p64"],["26","Un monde foot","A Football World (pun on 'un monde fou')","7c ?","20 m","Finishing variant of route 25. Really steep.","p64"],["27","Et dieu créa la flemme","And God Created Laziness","7a","22 m","Disconcerting climbing with a weird corner and a tough little roof. Fun overall.","p64"],["28","Tant qu'il y aura des freins à main","As Long as There Are Handbrakes","6b","22 m","Nice arête line. Climbing on big holds with feet that aren't always visible.","p64"]]}],"info":{"credits":"Unofficial English adaptation of <i>Escalade Saffres en Terres d'Auxois</i> (6th edition, 2021) by Yannick Dupin, published with the Communauté de Communes des Terres d'Auxois (CCTA). Layout &amp; maps: Rochana HM. Photos: © Matthias Paré. Buying the book (€19, e.g. at the Vitteaux tourist office) funds bolting and upkeep of the crag. Translations may contain mistakes — when in doubt, check the original pages included with each sector.","sections":[{"id":"access","title":"Getting there & map","pages":["p04"],"blocks":[{"img":"p04L","cap":"Access map. Dotted = footpaths, thin line = tracks, teal = roads, red = climbing site. Saffres is off the A6 (exit 23, Vitteaux), between Vitteaux and Dijon."},{"p":"From Saffres village, the parking is about 800 m away. Go through the barrier and park at <b>P</b>; there are toilets by the lower car park."},{"img":"p04R","cap":"Sector map. Dotted = footpath, white line = top of the cliff, hatched = poor-quality rock, tree = camping area, key icon = ask for the key at the town hall (mairie). DZ = helicopter landing area."},{"h":"Walk-in from the car park"},{"ul":["Sector 1: about 4 minutes","Sector 14: about 10 minutes","Sector 16: about 6–8 minutes"]},{"h":"Sectors and route numbers"},{"table":[["Sector","Routes"],["1 · Rêve d'enfant","1–23"],["2 · Pimprenelle","24–48"],["3 · Floconnerie","49–70"],["4 · Les Auxerrois","71–99"],["5 · La Kir","100–136"],["6 · La Troyenne","137–155"],["7 · La Voie de l'arbre","156–167"],["between 7 & 8 · Le curé de Miraude, L'enfant de chœur","bolting postponed, poor rock"],["8 · Vieille maîtresse","174–193"],["9 · Le Boulevard à Mathieu","194–206"],["10 · Robert clef de 12","207–227"],["11 · Magie blanche","227-1–240"],["12 · Damoclès","241–260"],["13 · Sans nom","261–299"],["14 · Grand Steak (being re-bolted)","300–320"],["15 · Tour Carrée","North face 1–10 · West 11–23 · South 24–33 · East 34–42"],["16 · Tour Penchée","South & East faces 1–13 · West face 14–28"]],"head":true}]},{"id":"intro","title":"Introduction & crag rules","pages":["p02"],"blocks":[{"p":"<b>You are holding the sixth edition of the Saffres crag topo.</b> By buying this topo you indirectly contribute to the bolting and upkeep of the site. Be aware that duplicates or photocopies are very much frowned upon at the crag. You have been warned."},{"p":"The Saffres climbing site, also called the “Groupe des Rochers de Miraude”, is a sport-climbing site with 400 routes equipped with glue-in bolts. Overall the routes are accessible (most are in the 5s and 6s)."},{"p":"The best climbing seasons are March to June and September to November. The cliff faces south, dries quickly and has little seepage. Read the topo carefully — many variants and traverses have been opened."},{"p":"The climbing is usually on very good compact limestone, with rare areas of loose/fractured rock. Some sections may be polished, mainly on the easy routes."},{"p":"After the re-bolting I carried out, the route names are the same as in the very first topo; I have only named a few new variants. Some grades have been raised because of the extra fatigue caused by the new clipping. There is still some commitment, but there are no longer any overly exposed (run-out) routes. Still, keep in mind that you are responsible for your own safety."},{"h":"Crag rules"},{"ul":["Avoid shouting during your attempts; respect the wildlife and don't disturb it.","Respect the parking areas.","Take your rubbish home, including cigarette butts.","Fires are forbidden throughout the whole commune.","There are no bins on site — leave with your rubbish.","No chipping/creating holds here.","Safety: climbing outdoors, if badly practised, is potentially fatal. Precise, effective belaying is essential. If needed, ask a professional or a club to help you improve your knowledge.","The bolts are relatively reliable, but the rock is not — it remains a living, fragile material. So be careful."]},{"p":"A topo is not always an infallible source, so there may be some errors or omissions left; thank you for your indulgence. And finally: <b>HAPPY CLIMBING!</b>"}]},{"id":"safety","title":"Safety at the crag","pages":["p67"],"blocks":[{"p":"<b>Every climber is responsible for assessing the risks they take when they set off on a route.</b> Several factors will help you assess these risks correctly:"},{"ul":["Your knowledge of safety techniques.","Your knowledge of the natural environment and its hazards.","Your knowledge of equipment/bolting.","How self-sufficient you are with safety, and your years of experience."]},{"p":"For relaxed outdoor climbing you therefore need sufficient knowledge and skill. If that's not the case, I encourage you to call on a professional or a club who can teach you good technique and give you good advice."},{"h":"Non-exhaustive list of recommendations for climbing outdoors"},{"ul":["Adjust your harness properly.","Wear a helmet.","Regularly check the wear of your PPE: slings, ropes…","Tie a knot in the end of the rope.","Know how to tie in to your harness correctly.","Master lead and top-rope belaying techniques.","Check each other before climbing.","Spot the climber before the first bolt.","Clip quickdraws correctly.","Communicate with your belayer, especially when lowering/threading the rope.","Master the lower-off procedure at the anchor (threading the quick-link).","Never top-rope directly through slings.","Know how to recognise reliable anchors.","Know how to recognise loose or potentially unstable rock, and test your holds."]},{"h":"Reporting problems"},{"p":"If you notice anything significant on site (bolting problem, unstable block…), you can report it to:"},{"ul":["Yannick Dupin, the author and route-setter (contact details on the original page below).","La Communauté de Communes des Terres d'Auxois: <a href=\"tel:+33380972665\">03 80 97 26 65</a>","The Ministry's SURICATE site (Sports de Nature resource centre): <a href=\"https://sentinelles.sportsdenature.fr\">sentinelles.sportsdenature.fr</a>"]}]},{"id":"glossary","title":"Glossary (French climbing terms)","pages":["p66"],"blocks":[{"p":"French terms you'll see on the original pages and hear at the crag, with the book's definitions translated."},{"dl":[["À vue — onsight","Climbing a route cleanly on the first attempt, without knowing it beforehand."],["Artif., artificielle — aid climbing","Where there are no holds, the climber's progress is helped by artificial aid points (pitons, bolts, nuts) used for pulling on."],["Athlétique — athletic","A climbing style or route that relies heavily on muscle. Rather gymnastic climbing."],["Bac — jug","A large, deep hold that's easy to hold."],["Cheminée — chimney","A wide crack you can fit your body into and climb using opposition techniques."],["Coincement, coincer — jamming","The climber wedges fingers, hands, feet… into holes or cracks."],["Continu, continuité (conti.) — continuous","Fairly sustained, consistent and long climbing without real rests, that you have to manage through rhythm and breathing."],["Cotation — grade","A route's difficulty level."],["Crux","The key section of a pitch or route."],["Dalle — slab","A generally smooth wall of low angle… 'slabby', a style that has been losing popularity since the late '80s."],["Délité(e) — loose, fractured","A route or rock that is at risk because of its instability."],["Dévers — overhang, steep ground","A wall that leans out beyond vertical."],["Dièdre — corner, dihedral","Where two faces of the cliff meet to form an angle, which climbers use by alternately opposing feet and hands."],["Dülfer — layback","A German mountaineer who gave his name to an opposition technique for climbing cracks and corners."],["Engager, engagement — committing","A committing route, with 'airy' (spaced) bolts, usually leaves memories. Subjective risk-taking by the climber."],["Exposé — exposed, dangerous","A route (or move) whose obsolete or badly placed equipment makes it potentially dangerous in a fall. Objective risk-taking by the climber."],["Fin, finesse — delicate","Describes balance climbing on small holds, mostly on slabs."],["Gaz, gazeux — exposure, airy","The void below you, which gives your climb its atmosphere…"],["Lecture — reading","Working out your route, either from the bottom or while climbing."],["Libérer, libre — free climb","Climbing a route that used to be aided, without aid points, using only natural holds."],["Ligne — line","Term for the path of a route and its overall aesthetics."],["Morphologique (morpho) — reachy, morpho","A move adapted to a certain body type, usually favouring tall people."],["Moulinette (moule) — top-rope","Belaying a climber from the ground, the rope having first been passed through the lower quick-link of the anchor at the top of the route."],["Mouvement (mouv.) — move","A body position that lets you make a climbing move."],["Opposition (oppo.) — bridging, opposition","A move that lets you progress by pushing in opposite directions in particular rock features: chimney, corner, flake."],["Ouverture, ouvrir — route setting, first ascent","Spotting a line, cleaning it and bolting it on a natural crag; indoors, placing holds on a wall (also called 'screwing on' holds)."],["Pas — move, crux move","Made up of one or two movements."],["Patiné(e) — polished","Said of rock or a route that is very worn and shiny from repeated passages."],["Placement — body positioning","A particular body position that lets you make a move."],["Point (d'ancrage) — protection point, bolt","Fixed (hangers, glue-in bolts) or removable (nuts, rope slings) points that protect the climber in a fall."],["Réglette — crimp, edge","A small horizontal hold, more or less incut, that you can make the most of by crimping it."],["Relais — anchor, belay","Where the lead climber stops to clip in and be lowered on top-rope. The anchor must be installed on two anchor points linked by a chain with quick-links."],["Résistance (rési.) — endurance, stamina, pumpy","What lets you hold onto small holds for a long time on hard routes without resting."],["Rétablissement (réta) — mantel","The move made to get over an overhang or onto a ledge."],["Rythme — rhythm","Not lingering in the hard sections and slowing down to recover on the easier ones — finding the right rhythm on the route."],["Technique — technical","Everything that makes climbing more than a sport of pulling on holds: positioning, tricks, rhythm…"],["Tirage — rope drag","…of the rope, whose path is slowed by obstacles (roofs, quickdraws at sharp angles…), which therefore hinders the climber."],["Toit — roof","A feature perpendicular to the wall."],["Traversée (trav.) — traverse","A part of the climb that runs horizontally or diagonally."],["Verrou — lock, jam","Wedging fingers, hands, feet, sometimes knees in a crack. Used especially on big walls in the USA."],["Verticale — vertical hold, side-pull","A vertical hold that requires positioning accordingly."],["Vire — ledge","A terrace or system of sometimes very narrow terraces crossing a wall (e.g. the middle ledge at Presles)."],["Vol, voler — fall, to fall","A fall by a climber who is leading."],["Zipper — slip","Your foot slipping — whether or not you catch yourself, it can lead to a fall."]]},{"h":"Other words on the original pages"},{"dl":[["Voie","Route"],["Niveau","Grade"],["Hauteur","Height"],["Secteur","Sector"],["Orienté Sud / Est / Ouest","Facing south / east / west"],["Écaille","Flake"],["Fissure","Crack"],["Pilier","Pillar"],["Surplomb","Overhang"],["Arête","Arête, edge"],["Bombé","Bulge"],["Conque","Scoop, concave bowl"],["Pince","Pinch"],["Plat","Sloper"],["Variante de départ / de sortie","Starting / finishing variant"],["R1 / R2 (longueur)","Pitch 1 / pitch 2"],["Broches","Glue-in bolts"],["Dégaines","Quickdraws"],["Mairie","Town hall"]]}]},{"id":"history","title":"History of the crag","pages":["p65"],"blocks":[{"p":"<i>Note: the first column of this chapter was cut off in the scan, so the beginning (early history: the first routes in the 1930s–40s by alpinists such as F. Bâtier (GHM), about a dozen routes climbed on top-rope or aid, including La Marguerite, Dièdre de Grand Vé and La Montagne, later developments with around 90 routes, and expansions by G. Romain and J. Recorbet) is only partly legible. What follows is the legible part.</i>"},{"p":"…legendary routes to climb (Le Balancier, La Mondette, La Gus, La Quille, La Caporal…). Climbing became more and more of a sport and began to break away from mountaineering."},{"p":"<b>1977:</b> Free ascent of “Le Rateau” by J.C. Droyer — the first French 6c in climbing history. This incredible performance was the world's 5th 6c in free climbing. The free-climbing era was under way."},{"p":"<b>1980:</b> Ascent of “Le Boulevard à Mathieu”, the third French 7b, by the gifted climber/alpinist of the time, Benoit Grison."},{"p":"<b>1985/1988:</b> A big wave of bolting by J.Y. Gerbet and J. Wiedmer, supported by the CAF Dijon. The cliff was now equipped with stainless-steel bolts set in mortar. The lowering system was a home-made one known as the “pig's tail” or “Moulinox”. In total about 450 routes were equipped with bolts and Moulinox."},{"p":"<b>1988:</b> Publication of a very complete topo with 450 routes plus about thirty routes in the western group (adventure terrain with mountain grades), republished in 1993 (CAF, J.Y. Gerbet)."},{"p":"<b>1989:</b> First “4 heures de Saffres” (4 Hours of Saffres), organised by the Club Alpin Français de Dijon — a national competition with lots of media coverage, featuring the best climbers of the time, such as Jean-Marc Boivin… The event was dropped because of the unpredictable weather and uncertain media interest. It was revived locally a few years later by the CT FFME 21 from 2012."},{"p":"<b>From 1997:</b> The first bolter/climber to start modifying the bolting at Saffres was J.Y. Leguy, a colleague and friend, who re-bolted about ten routes with a few extra bolts and some lines bolted in remote sectors that aren't in this topo. This state-certified instructor then turned to bolting the Gérigny cliff in 1998."},{"p":"<b>2007:</b> A new topo published by the Club Alpin Français, by O. Juaneda and Ph. Ducrot (with drawings and watercolours)."},{"p":"<b>2013–2015:</b> The CT FFME 21 replaced the Moulinox anchors with standard chain-and-quick-link anchors. I carried out the replacement of more than 400 anchors on behalf of the FFME, funded by the Communauté de Communes de Vitteaux."},{"p":"<b>2017–2019:</b> With the merger of the communities of communes in 2017, the Communauté de Communes des Terres d'Auxois (CCTA) was created and took responsibility for maintaining the site. I was therefore commissioned by the CCTA for the upkeep and annual maintenance, as with the other sites in the area."},{"p":"To limit risks, it was first necessary — before talking about maintenance — to make the route starts safe and to complete the bolting, notably on easy routes that were too exposed for leading. So about 1,000 bolts were glued in and about 300 bolts removed over those 3 years."}]},{"id":"geology","title":"Geology","pages":["p67"],"blocks":[{"img":"p67R","cap":"Geological cross-section (south-west to north-east)"},{"p":"<b>Saffres is a place rich and diverse in landscapes and natural features linked to the local geology.</b>"},{"p":"The Saffres cliff is made of limestone dating from the Jurassic (Mesozoic era, about 170 million years ago). This rock, formed from consolidated marine sediment, has been eroding ever since the seas withdrew."},{"p":"The surrounding landscape reflects the local geology well: a plateau at the top with small wooded hills here and there (limestone formation j2a and clayey limestone j1b in the illustration), and valleys with clay lower slopes that are often prone to landslides (formations l 6-5), topped by cliffs of the same limestone as the Saffres cliff (formation j1a). The foot of the cliff is cluttered with a chaos of fallen limestone blocks that hide the clays."},{"p":"Sometimes large masses of limestone slide on the surface of the clays: that is the case of the Tour Carrée, which was originally pressed against the cliff. It is also the case of the Tour Penchée, which partly toppled onto its side as it slid (rest assured, it takes time — you won't feel it move while you're climbing!)."},{"p":"Water flowing through the rock over thousands of years has created a network of fissures, cavities, tunnels… called a karst network, producing typical, easily visible features such as the natural tunnel of the Tour Carrée (which your children will love crossing). It can also deposit concretions (often good holds, but sometimes fragile) or calcite crystals, like those you can see on route 55 “Floconnerie”. Erosion has sometimes exposed the remains of marine organisms that make up much of the rock, giving it a more or less rough and abrasive surface."},{"p":"A spring, which historically supplied the village with drinking water, is tapped below the cliff. Water flows quickly through the cracks in the limestone and between the fallen blocks, and the ground has no filtering power. <b>So please avoid peeing upstream of this spring — that is, at the foot of the cliff and on the summit plateau — out of respect for the residents and their health.</b>"},{"p":"You can also see orchids, typical of these limestone soils."},{"p":"<i>Written by Anne-Laure Guillermin, geotechnical engineer, and Emmanuel Soncourt, hydrogeologist.</i>"}]},{"id":"nature","title":"Wildlife & the peregrine falcon","pages":["p68"],"blocks":[{"h":"Fauna and flora"},{"p":"<b>At Saffres you'll meet forest species (fox, roe deer, badger…) as well as cliff-dwelling species (lizards, bats, owls…).</b>"},{"p":"The cliff can be a home for some species (jackdaws' nests in the holes of the Tour Carrée, a natural beehive on the route “Le Pigeon à Odette”…), a breeding site for others (peregrine falcon nesting) and also a roost (tawny owl in the Grotte aux Filles)."},{"p":"The cliff is a biotope in its own right. I won't list every species living here — there are so many."},{"p":"The Saffres cliffs are listed as a ZNIEFF (Natural Area of Ecological, Faunal and Floral Interest), and regular surveys take place as part of this. ZNIEFF listing allows better management of the environment. Plant surveys are carried out by the Conservatoire des Espaces Naturels de Bourgogne."},{"p":"Some species are protected (fauna and flora) — for example the viper, which you may come across at Saffres. It is forbidden to move them; if you see one, leave it alone."},{"p":"The same goes for some birds of prey, notably the peregrine falcon, an emblematic species at Saffres: a pair of peregrines returns every year to nest."},{"h":"The peregrine falcon (Falco peregrinus)"},{"p":"<b>The peregrine falcon found on the cliffs of the Côte-d'Or belongs to the order Falconiformes and the genus Falco.</b>"},{"p":"A species with a worldwide distribution, it is present on every continent except Antarctica. It has fascinated people since Antiquity for its speed and hunting skills. In the Middle Ages, falconry was often practised by the nobility."},{"p":"The male can exceed 300 km/h during its spectacular courtship displays. The species is also very fast when catching prey, which are exclusively birds."},{"p":"Given its worldwide distribution, it has between 18 and 25 subspecies. The European population belongs to the subspecies Falco peregrinus peregrinus."},{"p":"In our regions it breeds mainly on cliffs. In the Côte-d'Or, the cliffs of the Auxois, the Arrière-côte, the Val Suzon and the Ouche valley offer very suitable nesting sites. In France it is not unusual for it to settle in towns to breed, using tall buildings such as churches, or factory chimneys and power-station cooling towers."},{"p":"Very attached to its breeding site, the pair is back from February. On a newly occupied site the pair may arrive later. The breeding season starts with courtship displays, with calls from the female and the male."},{"p":"Falcons don't build nests: the female just scrapes a hollow on a platform or ledge of the cliff, or settles in a cavity. Eggs are laid around mid-March, usually 3 or 4, sometimes 2 or 5."},{"p":"Incubation, by the female, lasts about 30 days and hatching is around mid-April. The young stay in the nest for about a month and a half before fledging."},{"p":"Throughout incubation the male hunts for the female and himself. After hatching, the male feeds the female and the young for 2 weeks while the female stays at the nest to watch over and warm them. Then the pair share the hunting."},{"p":"The brood fledges at the end of May / early June, but the pair and the young stay on site for 3 to 4 weeks, during which the male and female teach the young to hunt. This phase is essential before they become independent."},{"p":"<b>To protect this species, climbing is forbidden from 15 February to 15 June (APPB prefectoral biotope-protection order) on the “La Kir” sector (sector 5).</b>"},{"p":"<i>Written by Christian Lanaud — LPO (Ligue de Protection des Oiseaux, the French bird-protection league).</i>"}]},{"id":"tourism","title":"Nearby crags & rainy days","pages":["p69"],"blocks":[{"h":"Other climbing sites near Saffres"},{"table":[["Crag","Distance","Topo"],["Géligny (near Sombernon)","15 km","No topo yet"],["Hauteroche","20 km","FSGT topo available at Vieux Campeur"],["Vieux Château (Roches Sainte Catherine)","45 km","CC Terres d'Auxois topo, at the Semur-en-Auxois tourist office"],["Bouilland and Arcenant","45 km","Online topo on J.Y. Salin's blog “Escalade en Pays beaunois”"],["Cormot / Le Bout du Monde","60 km","CAF Chalon-sur-Saône topo"]],"head":true},{"h":"Where to climb when it rains?"},{"ul":["Climbing gym “Climb'Up Dijon” — 14 impasse Boirac, 21000 Dijon","Climbing gym “Cime Altitude 245 Dijon” — 14 rue Marius Chanteur, 21000 Dijon"]},{"h":"Welcome to Terres d'Auxois"},{"p":"Plan your stay with the Terres d'Auxois Tourist Office: accommodation, restaurants and takeaway, leisure activities, events, local services. Ask for the climbers' welcome booklet (digital version)!"},{"p":"On site, visit the tourist information office in <b>Vitteaux</b>, just 5 km from Saffres."},{"p":"Office de Tourisme des Terres d'Auxois · <a href=\"tel:+33380970596\">03 80 97 05 96</a> · contact@terres-auxois.fr · <a href=\"https://www.terres-auxois.fr\">www.terres-auxois.fr</a>"}]},{"id":"thanks","title":"Acknowledgements","pages":["p03"],"blocks":[{"ul":["A big thank-you to the first discoverers of some of the lines and other brave adventurers who, back in the day, were training here for big mountain routes.","A huge thank-you to the first CAF bolters, Guy Gerbet and his companions — visionaries who brought some incredible lines to life.","Thanks to the Communauté de Communes des Terres d'Auxois (CCTA), which supports the bolting and development of climbing in the area. In particular it funds the re-bolting of routes and the annual upkeep of the site. The whole climbing community is grateful.","Thanks to the CT FFME 21 for the material help of 180 bolts donated through an FFME bolting grant.","Thanks to the commune of Saffres for letting us climb in this magical place and for its support of climbers.","Thanks to everyone who took part, near or far, in creating this topo for their advice and expertise — Matthias, Anne-Laure, Emmanuel, Christian — and to all my climbing mates for the belays and other debates at the foot of the cliff. A big thank-you to you all…"]},{"p":"Graphic design, layout, cartography: Rochana HM. Printing: ADN Imprimerie, printed May 2021. Photo credits: © Matthias Paré."}]}]},"images":["img/p02L.webp","img/p02R.webp","img/p03L.webp","img/p03R.webp","img/p04L.webp","img/p04R.webp","img/p05L.webp","img/p05R.webp","img/p06L.webp","img/p06R.webp","img/p07L.webp","img/p07R.webp","img/p08L.webp","img/p08R.webp","img/p09L.webp","img/p09R.webp","img/p10L.webp","img/p10R.webp","img/p11L.webp","img/p11R.webp","img/p12L.webp","img/p12R.webp","img/p13L.webp","img/p13R.webp","img/p14L.webp","img/p14R.webp","img/p15L.webp","img/p15R.webp","img/p16L.webp","img/p16R.webp","img/p17L.webp","img/p17R.webp","img/p18L.webp","img/p18R.webp","img/p19L.webp","img/p19R.webp","img/p20L.webp","img/p20R.webp","img/p21L.webp","img/p21R.webp","img/p22L.webp","img/p22R.webp","img/p23L.webp","img/p23R.webp","img/p24L.webp","img/p24R.webp","img/p25L.webp","img/p25R.webp","img/p26L.webp","img/p26R.webp","img/p27L.webp","img/p27R.webp","img/p28L.webp","img/p28R.webp","img/p29L.webp","img/p29R.webp","img/p30L.webp","img/p30R.webp","img/p31L.webp","img/p31R.webp","img/p32L.webp","img/p32R.webp","img/p33L.webp","img/p33R.webp","img/p34L.webp","img/p34R.webp","img/p35L.webp","img/p35R.webp","img/p36L.webp","img/p36R.webp","img/p37L.webp","img/p37R.webp","img/p38L.webp","img/p38R.webp","img/p40L.webp","img/p40R.webp","img/p41L.webp","img/p41R.webp","img/p42L.webp","img/p42R.webp","img/p43L.webp","img/p43R.webp","img/p44L.webp","img/p44R.webp","img/p45L.webp","img/p45R.webp","img/p46L.webp","img/p46R.webp","img/p47L.webp","img/p47R.webp","img/p48L.webp","img/p48R.webp","img/p49L.webp","img/p49R.webp","img/p50L.webp","img/p50R.webp","img/p51L.webp","img/p51R.webp","img/p52L.webp","img/p52R.webp","img/p53L.webp","img/p53R.webp","img/p54L.webp","img/p54R.webp","img/p55L.webp","img/p55R.webp","img/p56L.webp","img/p56R.webp","img/p57L.webp","img/p57R.webp","img/p58L.webp","img/p58R.webp","img/p59L.webp","img/p59R.webp","img/p60L.webp","img/p60R.webp","img/p61L.webp","img/p61R.webp","img/p62L.webp","img/p62R.webp","img/p63L.webp","img/p63R.webp","img/p64L.webp","img/p64R.webp","img/p65L.webp","img/p65R.webp","img/p66L.webp","img/p66R.webp","img/p67L.webp","img/p67R.webp","img/p68L.webp","img/p68R.webp","img/p69L.webp","img/p69R.webp"],"imgCache":"saffres-img-d076710bed"};
